<script setup lang="ts">
import { t, locale } from '../i18n'
import { computed, reactive, ref } from 'vue'
import { ArrowLeft, BookOpenText, Eye, FilePenLine, LayoutDashboard, Plus, Search, Trash2, X, Check, ExternalLink } from 'lucide-vue-next'
import { useArticles } from '../store'
import OpsShell from '../components/OpsShell.vue'
import { articleImage } from '../articleImages'
import type { Article } from '../data'

const { articles, save, remove } = useArticles()
const search = ref('')
const statusFilter = ref('all')
const editing = ref(false)
const toast = ref('')
const emptyForm = () => ({ id: '', slug: '', title: '', excerpt: '', category: 'سبک زندگی', author: 'تحریریه مهرگان', readMinutes: 5, publishedAt: '', status: 'draft' as Article['status'], body: '', cover: 'mint' })
const form = reactive<Article>(emptyForm())
const filtered = computed(() => articles.value.filter(item => (statusFilter.value === 'all' || item.status === statusFilter.value) && (item.title.includes(search.value) || item.category.includes(search.value))))
const publishedCount = computed(() => articles.value.filter(item => item.status === 'published').length)
const draftCount = computed(() => articles.value.filter(item => item.status === 'draft').length)
function openNew() { Object.assign(form, emptyForm()); editing.value = true; toast.value = '' }
function openEdit(item: Article) { Object.assign(form, item); editing.value = true; toast.value = '' }
function slugify(value: string) { return value.trim().toLowerCase().replace(/\s+/g, '-').replace(/[^\p{L}\p{N}-]/gu, '') }
function persist() {
  const next = { ...form, id: form.id || `${Date.now()}`, slug: form.slug.trim() || slugify(form.title), publishedAt: form.publishedAt.trim() || new Intl.DateTimeFormat('fa-IR', { year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date()) }
  if (articles.value.some(item => item.slug === next.slug && item.id !== next.id)) { toast.value = 'این نشانی مقاله قبلاً استفاده شده است. نشانی دیگری وارد کنید.'; return }
  save(next)
  editing.value = false
  toast.value = 'مقاله در این مرورگر ذخیره شد.'
}
function toggle(item: Article) { save({ ...item, status: item.status === 'published' ? 'draft' : 'published' }); toast.value = 'وضعیت مقاله تغییر کرد.' }
function deleteArticle(item: Article) { if (window.confirm(`مقاله «${item.title}» حذف شود؟`)) { remove(item.id); toast.value = 'مقاله حذف شد.' } }
</script>

<template>
<OpsShell tab="magazine"><div class="magazine-admin ops-tab-content"><div class="admin-heading"><div><span class="kicker"><span class="kicker-dot"></span> {{ t("پنل مجله سلامت") }}</span><h1>{{ t("مقاله‌ها") }}</h1><p>{{ t("محتوای مجله را ایجاد، ویرایش و منتشر کنید.") }}</p></div><button class="button button-primary" type="button" @click="openNew"><Plus :size="19" /> {{ t("مقاله جدید") }}</button></div><div class="admin-stats"><div><span class="stat-icon"><BookOpenText :size="20" /></span><span>{{ t("همه مقاله‌ها") }}</span><strong>{{ articles.length.toLocaleString(locale()) }}</strong></div><div><span class="stat-icon"><Eye :size="20" /></span><span>{{ t("منتشرشده") }}</span><strong>{{ publishedCount.toLocaleString(locale()) }}</strong></div><div><span class="stat-icon"><FilePenLine :size="20" /></span><span>{{ t("پیش‌نویس") }}</span><strong>{{ draftCount.toLocaleString(locale()) }}</strong></div></div><div class="admin-panel"><div class="admin-panel-head"><div><h2>{{ t("فهرست مقاله‌ها") }}</h2><p>{{ t("برای تغییر وضعیت، روی «انتشار» یا «پیش‌نویس» بزنید.") }}</p></div><div class="admin-filters"><label class="search-field"><Search :size="17" /><input v-model="search" type="search" :placeholder="t('جست‌وجوی مقاله')" :aria-label="t('جست‌وجوی مقاله')" /></label><select v-model="statusFilter" :aria-label="t('فیلتر وضعیت')"><option value="all">{{ t("همه وضعیت‌ها") }}</option><option value="published">{{ t("منتشرشده") }}</option><option value="draft">{{ t("پیش‌نویس") }}</option></select></div></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>{{ t("مقاله") }}</th><th>{{ t("دسته‌بندی") }}</th><th>{{ t("تاریخ") }}</th><th>{{ t("وضعیت") }}</th><th>{{ t("عملیات") }}</th></tr></thead><tbody><tr v-for="item in filtered" :key="item.id"><td><span :class="['table-cover', `cover-${item.cover}`]"><img v-if="articleImage(item)" :src="articleImage(item)" alt=""/><BookOpenText v-else :size="20"/></span><span class="table-title"><strong>{{ t(item.title) }}</strong><small>{{ t(item.author) }}</small></span></td><td>{{ t(item.category) }}</td><td>{{ item.publishedAt }}</td><td><button type="button" :class="['status-pill', item.status]" @click="toggle(item)"><span></span>{{ t(item.status === 'published' ? 'منتشرشده' : 'پیش‌نویس') }}</button></td><td><div class="table-actions"><button type="button" :aria-label="t('ویرایش مقاله')" :title="t('ویرایش')" @click="openEdit(item)"><FilePenLine :size="18" /></button><RouterLink v-if="item.status === 'published'" :to="`/magazine/${item.slug}`" :title="t('نمایش مقاله')" :aria-label="t('نمایش مقاله')"><Eye :size="18" /></RouterLink><button type="button" class="danger" :aria-label="t('حذف مقاله')" title="حذف" @click="deleteArticle(item)"><Trash2 :size="18" /></button></div></td></tr></tbody></table><div v-if="!filtered.length" class="empty-state">{{ t("مقاله‌ای پیدا نشد.") }}</div></div></div><div v-if="toast" class="admin-toast" role="status"><Check :size="18" /> {{ t(toast) }}</div></div><div v-if="editing" class="modal-backdrop" @click.self="editing = false"><div class="editor-modal" role="dialog" aria-modal="true" :aria-label="t('ویرایش مقاله')"><div class="editor-head"><div><span class="kicker"><span class="kicker-dot"></span> {{ t("مجله سلامت") }}</span><h2>{{ t(form.id ? 'ویرایش مقاله' : 'مقاله جدید') }}</h2></div><button type="button" class="icon-button" :aria-label="t('بستن')" @click="editing = false"><X :size="22" /></button></div><form @submit.prevent="persist"><div class="form-grid"><label class="form-full"><span>{{ t("عنوان مقاله *") }}</span><input v-model.trim="form.title" required :placeholder="t('عنوانی روشن و کوتاه')" /></label><label class="form-full"><span>{{ t("خلاصه مقاله *") }}</span><textarea v-model.trim="form.excerpt" required rows="2" :placeholder="t('خلاصه‌ای برای کارت مقاله')"></textarea></label><label><span>{{ t("دسته‌بندی *") }}</span><select v-model="form.category" required><option value="سبک زندگی">{{ t("سبک زندگی") }}</option><option value="فیزیوتراپی">{{ t("فیزیوتراپی") }}</option><option value="سلامت روان">{{ t("سلامت روان") }}</option><option value="تغذیه">{{ t("تغذیه") }}</option><option value="بازتوانی">{{ t("بازتوانی") }}</option><option value="اخبار مهرگان">{{ t("اخبار مهرگان") }}</option></select></label><label><span>{{ t("نام نویسنده *") }}</span><input v-model.trim="form.author" required /></label><label><span>{{ t("زمان مطالعه (دقیقه) *") }}</span><input v-model.number="form.readMinutes" type="number" min="1" max="120" required /></label><label><span>{{ t("رنگ تصویر مقاله") }}</span><select v-model="form.cover"><option value="mint">{{ t("سبز آرام") }}</option><option value="blue">{{ t("آبی روشن") }}</option><option value="peach">{{ t("هلویی") }}</option><option value="lime">{{ t("سبز روشن") }}</option><option value="lavender">{{ t("یاسی") }}</option></select></label><label><span>{{ t("نشانی مقاله") }}</span><input v-model.trim="form.slug" dir="ltr" :placeholder="t('از عنوان ساخته می‌شود')" /></label><label><span>{{ t("وضعیت") }}</span><select v-model="form.status"><option value="draft">{{ t("پیش‌نویس") }}</option><option value="published">{{ t("منتشرشده") }}</option></select></label><label class="form-full"><span>{{ t("متن مقاله *") }}</span><textarea v-model.trim="form.body" required rows="8" :placeholder="t('برای تیتر اصلی از ## و برای زیرتیتر از ### در ابتدای خط استفاده کنید. پاراگراف‌ها را با خط خالی جدا کنید.')"></textarea></label></div><div class="editor-actions"><button type="button" class="button button-ghost" @click="editing = false">{{ t("انصراف") }}</button><button class="button button-primary" type="submit">{{ t("ذخیره مقاله") }} <Check :size="18" /></button></div><p v-if="toast" class="editor-error">{{ t(toast) }}</p></form></div></div></OpsShell>
</template>
